const inp = $input.first().json || {};
const raw = inp.body || {};
const srcEvent = raw.event || {};
const sd = $getWorkflowStaticData('global');
const miss = v => v === undefined || v === null || v === '' || v === '-';
const text = (v, max = 200) => {
  if (miss(v) || !['string', 'number', 'boolean'].includes(typeof v)) return '';
  return String(v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);
};
const num = v => Number.isFinite(Number(v)) ? Number(v) : undefined;
const rules = {
  R1: { stable: 'ACCOUNT_COMPROMISE', action: 'contain', events: ['account_compromise_suspected', 'account_locked'] },
  R2: { stable: 'DIRECT_PROMPT_INJECTION_BLOCKED', action: 'alert', events: ['prompt_injection_detected'] },
  R3: { stable: 'AI_TOOL_PERMISSION_DENIED', action: 'contain', events: ['agent_tool_call'] },
  R4: { stable: 'UNEXPECTED_INTERNAL_API_CALL', action: 'contain', events: ['internal_api_call'] },
  R5: { stable: 'ACCOUNT_SPRAY', action: 'alert', events: ['login_failure'] },
  R6: { stable: 'POST_LOCK_RETRY', action: 'alert', events: ['post_lock_retry_detected'] },
  R7: { stable: 'OFF_HOURS_LOGIN_SUCCESS', action: 'observe', events: ['login_success'] },
  R8: { stable: 'NOT_FOUND_SCAN', action: 'alert', events: ['not_found'] },
  R9: { stable: 'ADMIN_PATH_ACCESS_DENIED', action: 'alert', events: ['authz_deny'] },
  R10: { stable: 'DIRECT_CONFIDENTIAL_ACCESS_DENIED', action: 'alert', events: ['authz_deny'] },
  R11: { stable: 'REPEATED_AI_TOOL_PERMISSION_DENIAL', action: 'contain', events: ['agent_tool_call'] },
  R12: { stable: 'CONTENT_TRIGGERED_PROTECTED_TOOL_DENIAL', action: 'contain', events: ['agent_tool_call'] }
};
const expectedSeverity = {
  R1: { account_compromise_suspected: 'high', account_locked: 'medium' },
  R2: { prompt_injection_detected: 'high' }, R5: { login_failure: 'medium' },
  R6: { post_lock_retry_detected: 'high' }, R7: { login_success: 'info' },
  R8: { not_found: 'info' }, R9: { authz_deny: 'medium' }, R10: { authz_deny: 'medium' }
};
const id = text(raw.rule && raw.rule.id, 8);
const alertId = text(raw.alert && raw.alert.id, 160);
const contractValid = raw.schema_version === '1.1' && !!id && !!alertId && !!raw.event && typeof raw.event === 'object' && !Array.isArray(raw.event);
const ruleMeta = rules[id];
const evType = text(srcEvent.event_type, 80);
const severity = text(raw.rule && raw.rule.severity, 24).toLowerCase();
const actionLevel = text(raw.action_level, 24).toLowerCase();
const priority = num(raw.alert && raw.alert.priority);
const timestamp = text(raw.alert && raw.alert.timestamp, 64);
const timestampValid = !!timestamp && Number.isFinite(Date.parse(timestamp));
const stable = text(raw.rule && raw.rule.stable_name, 100);
const display = text(raw.rule && raw.rule.display_name, 180);
const supported = contractValid && !!ruleMeta && stable === ruleMeta.stable && ruleMeta.events.includes(evType);
const priorityValid = Number.isInteger(priority) && [1, 2, 3].includes(priority);
const severityValid = ['info', 'low', 'medium', 'high', 'critical'].includes(severity);
const severityMatches = !expectedSeverity[id] || expectedSeverity[id][evType] === severity;
const metadataValid = !!ruleMeta && stable === ruleMeta.stable && actionLevel === ruleMeta.action && severityValid && severityMatches && priorityValid && timestampValid;

// Strict allowlist: message/body/prompt/password/token/cookie and arbitrary Graylog fields are omitted.
const allowed = ['event_type', 'injection_type', 'source_type', 'source_component', 'trigger_source',
  'user', 'role', 'src_ip', 'request_id', 'session_id', 'tool_name', 'resource_class',
  'resource_id', 'trigger_resource_id', 'pattern_id', 'decision', 'reason', 'severity',
  'path', 'resource', 'required', 'count', 'window_seconds', 'failed_attempts',
  'lock_request_id', 'trigger_event_type'];
const event = {};
for (const key of allowed) {
  if (!Object.prototype.hasOwnProperty.call(srcEvent, key)) continue;
  const value = srcEvent[key];
  if (['count', 'window_seconds', 'failed_attempts'].includes(key)) {
    const n = num(value);
    if (Number.isFinite(n)) event[key] = n;
  } else {
    const v = text(value, ['path', 'resource'].includes(key) ? 240 : 180);
    if (v) event[key] = key === 'decision' ? v.toUpperCase() : v;
  }
}
const evidenceAllow = new Set(['event_count', 'distinct_users', 'retry_count', 'denied_calls',
  'failed_attempts', 'success_after_failures', 'window_seconds', 'correlation_window_seconds',
  'after_event', 'prior_event_type', 'lock_request_id', 'trigger_event_type', 'timezone', 'local_time']);
if (srcEvent.evidence && typeof srcEvent.evidence === 'object' && !Array.isArray(srcEvent.evidence)) {
  const evidence = {};
  for (const [key, value] of Object.entries(srcEvent.evidence)) {
    if (!evidenceAllow.has(key)) continue;
    if (typeof value === 'number' && Number.isFinite(value)) evidence[key] = value;
    else if (typeof value === 'boolean') evidence[key] = value;
    else if (typeof value === 'string' && !miss(value)) evidence[key] = text(value, 160);
  }
  if (Object.keys(evidence).length) event.evidence = evidence;
}
const decision = text(event.decision, 16).toUpperCase();
const decisionValid = ['ALLOW', 'DENY', 'BLOCK', 'WARN', 'INFO'].includes(decision);
const hasDecision = decisionValid;
const srcIp = text(event.src_ip, 64);
const user = text(event.user, 80);
const ticketKey = srcIp ? 'ip:' + srcIp : (user ? 'user:' + user : '');
let evidenceValid = true;
if (id === 'R1' && evType === 'account_compromise_suspected') evidenceValid = Number(event.failed_attempts) >= 3 && Number(event.window_seconds) === 300;
if (id === 'R2') evidenceValid = event.injection_type === 'direct' && decision === 'DENY' &&
  ['ignore_previous_instructions', 'reveal_hidden_prompt', 'policy_bypass_protected_data'].includes(event.pattern_id) &&
  !!user && !!srcIp && !!event.request_id && !!event.session_id;
if (id === 'R5') evidenceValid = !!srcIp;
if (id === 'R6') evidenceValid = evType === 'post_lock_retry_detected' && !!user && !!srcIp &&
  !!event.request_id && !!event.lock_request_id && Number.isInteger(event.count) && event.count >= 3 && Number(event.window_seconds) === 300;
if (id === 'R7') evidenceValid = !!user && !!srcIp;
if (id === 'R8') evidenceValid = !!srcIp;
if (id === 'R9') evidenceValid = !!user && !!event.path;
if (id === 'R10') evidenceValid = !!user && !!event.path && !!event.resource;
if (id === 'R3' || id === 'R11' || id === 'R12') evidenceValid = !!user && !!event.tool_name;
if (id === 'R4') evidenceValid = !!event.caller_service || !!event.source_component || !!srcIp;
if (id === 'R1' && evType === 'account_locked') evidenceValid = true;

const decisionConsistent = id === 'R1'
  ? (evType === 'account_compromise_suspected' ? decision === 'WARN' : ['DENY', 'BLOCK'].includes(decision))
  : id === 'R2' ? decision === 'DENY'
  : ['R3', 'R11', 'R12'].includes(id) ? decision === 'DENY'
  : id === 'R5' ? (!hasDecision || decision === 'DENY')
  : id === 'R6' ? (!hasDecision || decision === 'WARN')
  : id === 'R7' ? (!hasDecision || decision === 'ALLOW')
  : id === 'R8' ? (!hasDecision || decision === 'INFO')
  : ['R9', 'R10'].includes(id) ? (!hasDecision || ['DENY', 'BLOCK'].includes(decision))
  : id === 'R4' ? (!hasDecision || ['ALLOW', 'DENY', 'BLOCK'].includes(decision)) : false;
const autoAllowed = contractValid && supported && metadataValid && evidenceValid && hasDecision && decisionConsistent &&
  !['R1', 'R2', 'R4', 'R5', 'R6', 'R7', 'R8', 'R9', 'R10'].includes(id);
const notificationAllowed = contractValid && supported && stable === ruleMeta.stable && priorityValid && timestampValid &&
  severityValid && severityMatches && evidenceValid && actionLevel === ruleMeta.action && hasDecision && decisionConsistent;
let responseGroup = 'notify';
if (supported && id === 'R1') responseGroup = 'lock';
if (autoAllowed && ['R3', 'R11', 'R12'].includes(id)) responseGroup = 'session_ai';
if (supported && id === 'R4' && metadataValid) responseGroup = 'token';
const eventTypeSeverity = expectedSeverity[id] && expectedSeverity[id][evType];
const plannedActions = id === 'R1' && evType === 'account_compromise_suspected'
  ? ['이상 징후 경보', '티켓', '자동 계정 잠금 금지']
  : id === 'R1' && evType === 'account_locked'
    ? ['기존 잠금 결과 기록', '티켓', '추가 잠금 금지']
    : ['알림', '티켓'];
if (['R3', 'R11', 'R12'].includes(id)) plannedActions.push('DENY 및 정책 검증 시 세션 종료', 'AI Tool 제한은 pending');
if (id === 'R4') plannedActions.push('내부 API 토큰 폐기는 placeholder/pending');

let fallbackReason = '';
if (!contractValid) fallbackReason = 'schema_version_or_required_envelope_field_invalid';
else if (!supported) fallbackReason = 'unsupported_rule_or_stable_name_or_event_type';
else if (!priorityValid) fallbackReason = 'graylog_priority_must_be_1_to_3';
else if (!timestampValid) fallbackReason = 'alert_timestamp_missing_or_invalid';
else if (!evidenceValid) fallbackReason = 'rule_evidence_missing_or_invalid';
else if (!metadataValid) fallbackReason = 'rule_metadata_missing_or_invalid';
else if (!hasDecision) fallbackReason = 'decision_missing_or_invalid';
else if (!decisionConsistent) fallbackReason = 'decision_inconsistent_with_rule';
else if (!ticketKey) fallbackReason = 'no_safe_ticket_key';
const seen = sd.seen && typeof sd.seen === 'object' && !Array.isArray(sd.seen) ? sd.seen : {};
const duplicate = !!alertId && !!seen[alertId];
if (duplicate) fallbackReason = 'duplicate_alert_id';
const cfg = inp;
const mode = cfg.response_mode === 'live' ? 'live' : 'dry-run';
const liveEnabled = cfg.live_enabled === true;
const severityLabel = severity || '';
const bits = [`[${id || 'UNKNOWN'}] ${display || stable || '지원하지 않는 규칙'}`, `출발지 ${srcIp || (user ? 'user:' + user : '-')}`, `계정 ${user || '-'}`, `이벤트 ${evType || '-'}`];
if (Number.isFinite(event.count)) bits.push(`${event.count}건`);
if (hasDecision) bits.push('판정 ' + decision);
if (event.tool_name) bits.push('Tool ' + event.tool_name);
if (severityLabel) bits.push('심각도 ' + severityLabel);
if (plannedActions.length) bits.push('대응 계획: ' + plannedActions.join(', '));
return [{ json: {
  schema_version: text(raw.schema_version, 8), contract_valid: contractValid,
  rule_id: id, rule: { id, stable_name: stable, display_name: display, severity: severity || undefined },
  alert: { id: alertId, timestamp, priority }, event, severity: severity || undefined,
  src_ip: srcIp, user, request_id: text(event.request_id, 120), session_id: text(event.session_id, 120),
  tool_name: text(event.tool_name, 120), count: Number.isFinite(event.count) ? event.count : 1,
  first_seen: timestamp, last_seen: timestamp,
  graylog_event_id: alertId, ticket_key: ticketKey,
  ticket_type: id === 'R1' && evType === 'account_locked' ? '잠금 결과 기록' : (id === 'R1' ? '이상 징후 경보' : '보안 경보'),
  response_group: responseGroup, actions: plannedActions, message: bits.join(' | '),
  decision, action_level: actionLevel, auto_response_allowed: autoAllowed,
  discord_enabled: mode === 'live' && liveEnabled && notificationAllowed && actionLevel !== 'observe',
  response_mode: mode, live_enabled: liveEnabled,
  lock_minutes: cfg.lock_minutes, whitelist_ips: Array.isArray(cfg.whitelist_ips) ? cfg.whitelist_ips : [],
  duplicate, skip_side_effects: duplicate || !!fallbackReason, fallback_reason: fallbackReason || undefined,
  rule_metadata_severity: severity || undefined,
  priority_source: 'graylog.alert.priority', priority_preserved: priority
} }];

const d = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.tickets = sd.tickets || {};
sd.history = sd.history || [];
sd.whitelist = sd.whitelist || {};
sd.skipped = sd.skipped || [];
sd.seq = sd.seq || 0;
const rememberAlert = id => {
  if (!id) return;
  const seen = sd.seen && typeof sd.seen === 'object' && !Array.isArray(sd.seen) ? sd.seen : {};
  seen[id] = Date.now();
  sd.seen = seen;
  const keys = Object.keys(seen);
  if (keys.length > 500) for (const key of keys.sort((a, b) => seen[a] - seen[b]).slice(0, keys.length - 500)) delete seen[key];
};
const whitelist = Array.isArray(d.whitelist_ips) ? d.whitelist_ips.map(String) : [];
if (d.src_ip && (whitelist.includes(d.src_ip) || sd.whitelist[d.src_ip])) {
  sd.skipped.unshift({ time: d.last_seen, src_ip: d.src_ip, rule_id: d.rule_id });
  sd.skipped = sd.skipped.slice(0, 50);
  rememberAlert(d.graylog_event_id);
  return [{ json: { ...d, whitelisted: true, skip_side_effects: true } }];
}
const rank = { '이상 징후 경보': 1, '보안 경보': 1, '잠금 결과 기록': 2, '차단 조치': 2, '침해 인시던트': 3 };
const key = d.ticket_key;
if (!key) return [];
let t = sd.tickets[key];
let isNew = false;
if (t && t.status === 'closed') { sd.history.push(t); t = null; }
if (!t) {
  sd.seq += 1;
  t = { id: 'NX-' + String(sd.seq).padStart(4, '0'), ticket_key: key, src_ip: d.src_ip || '',
        type: d.ticket_type, rules: [], users: [], count: 0, first_seen: d.first_seen, last_seen: d.last_seen, status: 'open' };
  isNew = true;
}
if ((rank[d.ticket_type] || 0) > (rank[t.type] || 0)) t.type = d.ticket_type;
if (!t.rules.includes(d.rule_id)) t.rules.push(d.rule_id);
if (d.user && !t.users.includes(d.user)) t.users.push(d.user);
t.count += Number(d.count) || 1;
t.last_seen = d.last_seen;
t.latest = { rule: d.rule, alert: d.alert, event: d.event, action_level: d.action_level, decision: d.decision };
sd.tickets[key] = t;
rememberAlert(d.graylog_event_id);
return [{ json: { ...d, ticket_id: t.id, ticket_is_new: isNew, ticket_type: t.type,
  ticket_rules: t.rules, ticket_users: t.users, ticket_event_total: t.count,
  message: `[${t.id} ${isNew ? '신규' : '갱신'}] ` + d.message } }];

const input = $input.first().json || {};
const sd = $getWorkflowStaticData('global');
sd.tickets = sd.tickets || {}; sd.history = sd.history || []; sd.whitelist = sd.whitelist || {}; sd.skipped = sd.skipped || [];
const configured = Array.isArray(input.whitelist_ips) ? input.whitelist_ips.map(String) : [];
const all = [...Object.values(sd.tickets), ...sd.history].sort((a, b) => (a.id < b.id ? 1 : -1));
const open = all.filter(t => t.status === 'open');
const by_type = {};
for (const t of open) by_type[t.type] = (by_type[t.type] || 0) + 1;
return [{ json: { http: 200, body: {
  generated_at: new Date().toISOString(),
  summary: { open: open.length, closed: all.length - open.length, by_type },
  tickets: all,
  whitelist: [...configured.map(ip => ({ ip, source: '환경설정' })), ...Object.entries(sd.whitelist).map(([ip, v]) => ({ ip, source: '상황판', ...v }))],
  skipped: sd.skipped.slice(0, 10)
} } }];

const input = $input.first().json || {};
const sd = $getWorkflowStaticData('global');
sd.tickets = sd.tickets || {}; sd.history = sd.history || []; sd.whitelist = sd.whitelist || {}; sd.skipped = sd.skipped || [];
const configured = Array.isArray(input.whitelist_ips) ? input.whitelist_ips.map(String) : [];
const b = input.body || {};
const now = new Date().toISOString();
const ipOk = ip => /^(?:\d{1,3}\.){3}\d{1,3}$/.test(String(ip || ''));
const res = (http, body) => [{ json: { http, body } }];
const userOk = u => /^[A-Za-z][A-Za-z0-9._-]{0,49}$/.test(String(u || ''));
const findT = id => Object.values(sd.tickets).find(x => x.id === id);
const mode = input.response_mode === 'live' && input.live_enabled === true ? 'live' : 'dry-run';
const lockMin = Math.min(Math.max(parseInt(input.lock_minutes, 10) || 15, 1), 1440);
const LABEL = { applied: '적용', no_change: '변경 없음', 'dry-run': '미실행(dry-run)', error: '오류' };
const addRec = (t, rec) => { t.responses = (t.responses || []).concat([rec]).slice(-30); };
if (b.action === 'close' || b.action === 'false_positive') {
  const t = Object.values(sd.tickets).find(x => x.id === b.ticket_id);
  if (!t) return res(404, { status: 'not_found' });
  if (t.status === 'closed') return res(409, { status: 'already_closed' });
  t.status = 'closed'; t.resolution = b.action === 'false_positive' ? '오탐' : '조치 완료'; t.closed_at = now;
  t.note = String(b.note || '').slice(0, 500);
  if (b.action === 'false_positive' && b.whitelist === true && ipOk(t.src_ip)) sd.whitelist[t.src_ip] = { added_at: now, reason: '오탐 ' + t.id };
  return res(200, { status: 'ok', ticket: t });
}
if (b.action === 'request_release') {
  const user = String(b.user || '').trim();
  if (!userOk(user)) return res(400, { status: 'bad_user' });
  const linked = b.ticket_id ? findT(b.ticket_id) : null;
  if (b.ticket_id && !linked) return res(404, { status: 'not_found' });
  sd.seq = (sd.seq || 0) + 1;
  const t = { id: 'NX-' + String(sd.seq).padStart(4, '0'), src_ip: linked ? linked.src_ip : '', type: '오탐·해제 요청',
    rules: [], users: [user], user, count: 1, first_seen: now, last_seen: now, status: 'open', linked_ticket: linked ? linked.id : null, reason: String(b.reason || '').slice(0, 300) };
  sd.tickets['request:' + t.id] = t;
  return res(200, { status: 'ok', ticket: t });
}
if (b.action === 'release' || b.action === 'lock') {
  const t = findT(b.ticket_id);
  if (!t) return res(404, { status: 'not_found' });
  const user = String(b.user || t.user || (t.users.length === 1 ? t.users[0] : '')).trim();
  if (!userOk(user)) return res(400, { status: 'bad_user', hint: 'user 를 지정하세요' });
  if (![...(t.users || []), t.user].includes(user)) return res(400, { status: 'user_not_in_ticket' });
  const rel = b.action === 'release';
  const ctx = { ticket_id: t.id, user, kind: b.action, mode, by: '상황판',
    step: rel ? '계정 잠금 해제' : '계정 잠금(사람 승인)', undo: rel ? '상황판의 "잠금(승인)"으로 다시 잠금' : 'locked_until = NULL (잠금 해제)' };
  if (mode !== 'live') {
    const rec = { time: now, step: ctx.step, user, mode, status: 'dry-run', label: LABEL['dry-run'], by: ctx.by, detail: 'dry-run(DB를 바꾸지 않음)', undo: ctx.undo };
    addRec(t, rec);
    return res(200, { status: 'ok', result: rec, ticket: t });
  }
  const sql = rel ? 'UPDATE users SET locked_until = NULL WHERE username = $1'
    : 'UPDATE users SET locked_until = DATE_ADD(NOW(), INTERVAL $1 MINUTE) WHERE username = $2';
  const verify = "SELECT '" + (rel ? 'release' : 'lock') + "' AS step_key, username, pinned, locked_until, (locked_until IS NOT NULL AND locked_until > NOW()) AS locked, session_version FROM users WHERE username = $1";
  return [{ json: { http: 200, body: null, db: { ...ctx, execute: input.live_enabled === true, sql, params: rel ? [user] : [lockMin, user], verify_sql: verify } } }];
}
if (b.action === 'whitelist_add') {
  if (!ipOk(b.ip)) return res(400, { status: 'bad_ip' });
  sd.whitelist[b.ip] = { added_at: now, reason: String(b.note || '수동 추가').slice(0, 200) };
  return res(200, { status: 'ok', ip: b.ip });
}
if (b.action === 'whitelist_remove') {
  if (!sd.whitelist[b.ip] && !configured.includes(String(b.ip || ''))) return res(404, { status: 'not_found' });
  delete sd.whitelist[b.ip];
  return res(200, { status: 'ok', ip: b.ip, note: configured.includes(String(b.ip || '')) ? '환경설정 whitelist는 설정 노드에서 관리' : undefined });
}
return res(400, { status: 'bad_action', allowed: ['close', 'false_positive', 'release', 'lock', 'request_release', 'whitelist_add', 'whitelist_remove'] });

const d = $input.first().json;
const mode = d.response_mode === 'live' ? 'live' : 'dry-run';
const live = mode === 'live' && d.live_enabled === true && d.auto_response_allowed === true;
const lockMin = Math.min(Math.max(parseInt(d.lock_minutes, 10) || 15, 1), 1440);
const user = String(d.user || '').trim();
const okUser = /^[A-Za-z][A-Za-z0-9._-]{0,49}$/.test(user);
const base = { ticket_id: d.ticket_id, ticket_key: d.ticket_key, rule_id: d.rule_id, user, mode,
  live_enabled: d.live_enabled === true, discord_enabled: d.discord_enabled };
const steps = [];
const VERIFY = k => "SELECT '" + k + "' AS step_key, username, pinned, locked_until, (locked_until IS NOT NULL AND locked_until > NOW()) AS locked, session_version FROM users WHERE username = $1";
if (d.response_group === 'lock' && d.auto_response_allowed === true) {
  steps.push({ step: '계정 잠금', sql: 'UPDATE users SET locked_until = IF(pinned = 0, DATE_ADD(NOW(), INTERVAL $1 MINUTE), locked_until), session_version = IF(pinned = 1, session_version + 1, session_version) WHERE username = $2',
    params: [lockMin, user], verify_sql: VERIFY('lock'), undo: 'UPDATE users SET locked_until = NULL WHERE username = ?', note: lockMin + '분' });
}
if (d.response_group === 'session_ai' && d.auto_response_allowed === true && d.decision === 'DENY') {
  steps.push({ step: '세션 종료(강제 로그아웃)', sql: 'UPDATE users SET session_version = session_version + 1 WHERE username = $1',
    params: [user], verify_sql: VERIFY('logout'), undo: '되돌릴 필요 없음(다시 로그인하면 됨)' });
  steps.push({ step: 'AI Tool 제한', pending: 'Tool Gateway 미구현: 실제 제한은 pending' });
}
if (!steps.length) steps.push({ step: '자동 대응 없음', skip_reason: d.rule_id === 'R1' ? 'R1은 기존 account_locked 결과 기록 또는 account_compromise_suspected 경보만 수행' : 'decision/action_level/metadata 확인 또는 구현 준비 전에는 자동 DB 조치 금지' });
return steps.map(s => ({ json: { ...base, ...s,
  execute: live && okUser && !!s.sql,
  skip_reason: s.skip_reason || (!s.sql ? (s.pending || s.skip_reason) : (!okUser ? (user ? '계정 이름 형식 오류' : '대상 계정 없음') : (!live ? 'dry-run 또는 live_enabled=false (DB를 바꾸지 않음)' : ''))) } }));

const prep = $('대응 준비(DB 조치)').all();
const sd = $getWorkflowStaticData('global');
const LABEL = { applied: '적용', partial: '일부 적용(세션 종료만)', no_change: '변경 없음', 'dry-run': '미실행(dry-run)', skipped: '건너뜀', error: '오류', pending: 'AI 연동 후 구현' };
let updErr = null;
try { updErr = $('DB 조치 실행').all().find(u => u.json && u.json.error) || null; } catch (e) {}
const execCtx = (prep.find(p => p.json.execute) || {}).json;
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  let ctx, status, detail = '', note;
  if (j.step) {                                   // DB를 거치지 않은 항목(dry-run·건너뜀·보류)
    ctx = j; detail = j.skip_reason || '';
    status = j.pending ? 'pending' : (String(j.skip_reason).startsWith('dry-run') ? 'dry-run' : 'skipped');
  } else {                                        // 조치 후 확인 조회 결과
    ctx = execCtx || {};
    if (updErr || j.error) { status = 'error'; detail = String((updErr ? updErr.json.message : j.message) || '').slice(0, 200); }
    else if (!j.username) { status = 'no_change'; detail = '대상 계정을 찾지 못함'; }
    else if (Number(j.pinned) === 1 && j.step_key === 'lock') { status = 'partial'; detail = '고정 계정: 잠금 없이 세션 종료만 실행. 잠금은 사람이 승인'; note = '세션 버전 ' + j.session_version; }
    else if (j.step_key === 'lock' && !Number(j.locked)) { status = 'error'; detail = '조치 후에도 잠금 상태가 아님'; }
    else { status = 'applied'; note = j.step_key === 'lock' ? ('잠금 해제 예정 ' + j.locked_until) : ('세션 버전 ' + j.session_version); }
  }
  const rec = { time: new Date().toISOString(), step: ctx.step, user: ctx.user, mode: ctx.mode, status, label: LABEL[status] };
  if (detail) rec.detail = detail;
  if (note || ctx.note) rec.note = note || ctx.note;
  if (ctx.undo) rec.undo = ctx.undo;
  const t = sd.tickets && sd.tickets[ctx.ticket_key];
  if (t) { t.responses = (t.responses || []).concat([rec]).slice(-30); }
  out.push({ json: { ...rec, ticket_id: ctx.ticket_id, rule_id: ctx.rule_id,
    discord_enabled: !!ctx.discord_enabled && ctx.live_enabled === true && ['applied', 'partial', 'no_change', 'error'].includes(status),
    message: `[${ctx.ticket_id}] 대응 결과: ${ctx.step} → ${LABEL[status]} | 대상 ${ctx.user || '-'}` + (rec.note ? ' | ' + rec.note : '') + (detail ? ' | ' + detail : '') } });
}
return out;

const ctx = $('티켓 처리·화이트리스트').first().json.db;
const sd = $getWorkflowStaticData('global');
const LABEL = { applied: '적용', no_change: '변경 없음', error: '오류' };
let updErr = null;
try { updErr = $('계정 조치 실행').all().find(u => u.json && u.json.error) || null; } catch (e) {}
const j = $input.first().json;
let status, detail = '', note;
if (updErr || j.error) { status = 'error'; detail = String((updErr ? updErr.json.message : j.message) || '').slice(0, 200); }
else if (!j.username) { status = 'no_change'; detail = '대상 계정을 찾지 못함'; }
else if (ctx.kind === 'release') {
  if (Number(j.locked)) { status = 'error'; detail = '조치 후에도 잠겨 있음'; } else { status = 'applied'; note = '잠금 해제됨'; }
} else {
  if (!Number(j.locked)) { status = 'error'; detail = '조치 후에도 잠금 상태가 아님'; } else { status = 'applied'; note = '잠금 해제 예정 ' + j.locked_until; }
}
const now = new Date().toISOString();
const rec = { time: now, step: ctx.step, user: ctx.user, mode: ctx.mode, status, label: LABEL[status], by: ctx.by, undo: ctx.undo };
if (detail) rec.detail = detail;
if (note) rec.note = note;
const all = Object.values(sd.tickets || {});
const t = all.find(x => x.id === ctx.ticket_id);
const push = x => { if (x) x.responses = (x.responses || []).concat([rec]).slice(-30); };
push(t);
if (t && t.linked_ticket) push(all.find(x => x.id === t.linked_ticket));
if (t && t.type === '오탐·해제 요청' && ctx.kind === 'release' && status === 'applied' && t.status === 'open') {
  t.status = 'closed'; t.resolution = '해제 승인'; t.closed_at = now;
}
return [{ json: { http: status === 'error' ? 502 : 200, body: { status: status === 'error' ? 'error' : 'ok', result: rec, ticket: t } } }];
